import { describe, expect, it } from 'vitest';
import { parseChordSymbol } from './chordSymbol';
import vocabRaw from './fixtures/chordonomicon-vocab.txt?raw';

// Every chord symbol the Chordonomicon index can contain (generated by
// tools/chord_index/common.py convert_chord over the whole dataset).
const vocab = vocabRaw
  .split('\n')
  .filter(Boolean);

describe('Chordonomicon chord vocabulary', () => {
  it('is non-trivial', () => {
    expect(vocab.length).toBeGreaterThan(1000);
  });
  it('every converted symbol parses', () => {
    const bad = vocab.filter((s) => parseChordSymbol(s) === null);
    expect(bad).toEqual([]);
  });
});
